  values ('deal:everton-football-club:777-partners:2023-09-15', '2023-09-15', null, 'acquisition', 'sports', 'football', 'Everton Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--everton'), null, '777 Partners', 'private_equity', (select id from public.companies where lower(name) = lower('777 Partners') limit 1), (select id from public.sports_investors where lower(name) = lower('777 Partners') limit 1), 'Farhad Moshiri', 94.1, 550000000, 'GBP', null, null, '777 Partners agrees to buy Moshiri''s 94.1% stake (deal later collapsed)', 'Miami-based 777 Partners signed an agreement on 15 September 2023 to acquire Moshiri''s 94.1% stake, reported at more than £550m, subject to regulatory approval. 777 lent the club over £200m during the process but never completed; the agreement lapsed at the end of May 2024.', 'ESPN', 'https://global.espn.com/football/story/_/id/38403548/everton-sold-us-private-equity-firm-777-partners-moshiri-premier-league', 'web_research')
